export const typeDefs = "\"\"\"\nGateway GraphQL API, consumed by the web backend-for-frontend. It serves reads and live updates;\ncommands (alert intake, approvals) go through the REST API in contracts/openapi/gateway.yaml.\nRequests need the X-API-Key header, like the REST /v1 routes.\n\"\"\"\ntype Query {\n  \"Gateway liveness for clients that only speak GraphQL.\"\n  health: Health!\n  \"Investigations, newest first, as a Relay cursor connection. `first` is at most 100.\"\n  investigations(first: Int = 20, after: String): InvestigationConnection!\n  \"One investigation, or null when the id is unknown.\"\n  investigation(id: ID!): Investigation\n}\n\ntype Subscription {\n  \"The investigation after each change, streamed over server-sent events.\"\n  investigationUpdated(id: ID!): Investigation!\n}\n\n\"RFC 3339 timestamp in UTC, for example 2026-10-14T12:00:05Z.\"\nscalar DateTime\n\ntype Health {\n  status: String!\n}\n\ntype InvestigationConnection {\n  edges: [InvestigationEdge!]!\n  pageInfo: PageInfo!\n}\n\ntype InvestigationEdge {\n  \"Opaque keyset cursor; pass it as `after` to read the next page.\"\n  cursor: String!\n  node: Investigation!\n}\n\ntype PageInfo {\n  hasNextPage: Boolean!\n  hasPreviousPage: Boolean!\n  startCursor: String\n  endCursor: String\n}\n\ntype Investigation {\n  id: ID!\n  \"Alert group that triggered the investigation.\"\n  groupId: ID!\n  title: String!\n  status: InvestigationStatus!\n  \"Final report summary; null until the investigation ends.\"\n  summary: String\n  \"Model tokens spent so far, input and output combined.\"\n  tokensUsed: Int!\n  createdAt: DateTime!\n  updatedAt: DateTime!\n  \"Best first.\"\n  hypotheses: [Hypothesis!]!\n  proposedActions: [ProposedAction!]!\n  \"In execution order.\"\n  steps: [Step!]!\n  \"\"\"\n  A live triage's verdict; null until the report, for simulated incidents, for a report written\n  after a stop, and for reports recorded before verdicts existed.\n  \"\"\"\n  verdict: Verdict\n  \"Every model asked, in the order first asked; empty until the report, and for older reports.\"\n  models: [ModelUse!]!\n}\n\n\"Whether a live alert shows an incident a human must look at. NOT_REAL never hides the alert.\"\nenum Verdict {\n  REAL\n  NOT_REAL\n}\n\n\"A model asked during an investigation, for one part of the work.\"\ntype ModelUse {\n  part: ModelPart!\n  provider: String!\n  model: String!\n  \"Requests it answered.\"\n  calls: Int!\n  \"Requests it did not answer, and requests skipped before they reached it.\"\n  failed: Int!\n  \"Why the last of those failed or was skipped; null when it answered every request.\"\n  reason: String\n}\n\nenum ModelPart {\n  \"The investigation's turns.\"\n  TRIAGE\n  \"Log page summaries.\"\n  SUMMARY\n}\n\nenum InvestigationStatus {\n  QUEUED\n  RUNNING\n  AWAITING_APPROVAL\n  RESOLVED\n  FAILED\n  CANCELLED\n}\n\ntype Hypothesis {\n  \"1 is the most likely root cause.\"\n  rank: Int!\n  rootCauseClass: RootCauseClass!\n  summary: String!\n  \"Between 0 and 1.\"\n  confidence: Float!\n  evidence: [Evidence!]!\n}\n\n\"Fixed root-cause classes, so evals compare classes instead of free text.\"\nenum RootCauseClass {\n  BAD_DEPLOY\n  CONFIG_CHANGE\n  DEPENDENCY_FAILURE\n  RESOURCE_EXHAUSTION\n  TRAFFIC_SURGE\n  DATABASE\n  INFRASTRUCTURE\n  CERTIFICATE_EXPIRY\n  UNKNOWN\n}\n\n\"An excerpt of a tool result that supports a hypothesis.\"\ntype Evidence {\n  \"Id of the tool result the excerpt comes from.\"\n  toolCallId: ID!\n  excerpt: String!\n}\n\n\"A remediation the agent proposes. Only the executor runs it, and only after a human approves it.\"\ntype ProposedAction {\n  id: ID!\n  kind: ActionKind!\n  \"Service the action applies to.\"\n  target: String!\n  parameters: [ActionParameter!]!\n  rationale: String!\n  status: ActionStatus!\n  proposedAt: DateTime!\n  \"Approver identity; null while pending.\"\n  decidedBy: String\n  decidedAt: DateTime\n}\n\n\"Allowlisted action kinds.\"\nenum ActionKind {\n  ROLLBACK_DEPLOY\n  RESTART_SERVICE\n  SCALE_SERVICE\n  DISABLE_FEATURE_FLAG\n}\n\nenum ActionStatus {\n  PENDING\n  APPROVED\n  REJECTED\n}\n\ntype ActionParameter {\n  name: String!\n  \"The value as display text, for example v1.7.3 or 4.\"\n  value: String!\n}\n\n\"One step of the agent loop.\"\ntype Step {\n  \"Position in the investigation, starting at 1.\"\n  seq: Int!\n  kind: StepKind!\n  summary: String!\n  \"Set on tool call steps only.\"\n  toolCall: ToolCall\n  recordedAt: DateTime!\n}\n\nenum StepKind {\n  TOOL_CALL\n  HYPOTHESIS\n  ACTION\n  REPORT\n}\n\ntype ToolCall {\n  \"Id of the tool result; evidence cites it.\"\n  id: ID!\n  name: String!\n  status: ToolCallStatus!\n  durationMs: Int!\n}\n\nenum ToolCallStatus {\n  OK\n  ERROR\n  TIMEOUT\n}\n";
